const canvas=document.getElementById('world'),ctx=canvas.getContext('2d'),mini=document.getElementById('minimap'),mctx=mini.getContext('2d');
const W=2200,H=1500,player={x:1110,y:790,hp:100,maxHp:100,xp:0,level:1,dir:1,anim:0,attack:0,dodge:0};let camera={x:0,y:0},keys={},mouse={x:0,y:0},moveTarget=null,attackTimer=0,skillCooldown=0,toastTimer,dialogOpen=false,worldClock=0;
const rand=(n)=>{let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
const trees=[],stones=[],flowers=[];
for(let i=0;i<180;i++){let x=rand(i+1)*W,y=rand(i+312)*H;if(Math.hypot(x-1110,y-790)<220)continue;if(x>810&&x<1390&&y>500&&y<1050&&rand(i+77)>.28)continue;trees.push({x,y,r:22+rand(i+98)*22,h:40+rand(i+141)*32,t:rand(i+36)})}
for(let i=0;i<60;i++)stones.push({x:rand(i+600)*W,y:rand(i+850)*H,r:4+rand(i+75)*9});
for(let i=0;i<220;i++)flowers.push({x:rand(i+1300)*W,y:rand(i+1500)*H,c:['#e3c36f','#d98c79','#d5d8a1','#b5bbd7'][i%4]});
const mobs=[];for(let i=0;i<7;i++){const a=i/7*Math.PI*2; mobs.push({x:1110+Math.cos(a)* (285+(i%3)*85),y:790+Math.sin(a)*(180+(i%2)*100),hp:42,maxHp:42,alive:true,respawn:0,attack:0,hit:0,dir:1,id:i})}
const npc={x:925,y:695,name:'Elder Rowan'};let last=performance.now(),chat=document.getElementById('chat');
function resize(){const dpr=Math.min(devicePixelRatio||1,2);canvas.width=innerWidth*dpr;canvas.height=innerHeight*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function roundRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r)}
function drawGround(){ctx.fillStyle='#496343';ctx.fillRect(0,0,W,H);
// subtle lush noise patches
for(let i=0;i<260;i++){const x=rand(i+1900)*W,y=rand(i+2400)*H,r=18+rand(i+2600)*55;ctx.fillStyle=i%2?'rgba(130,151,87,.09)':'rgba(28,57,38,.10)';ctx.beginPath();ctx.ellipse(x,y,r,r*.5,rand(i+40),0,Math.PI*2);ctx.fill()}
// footpath
ctx.save();ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(-100,970);ctx.bezierCurveTo(400,910,480,750,810,800);ctx.bezierCurveTo(1110,845,1220,1060,1560,970);ctx.bezierCurveTo(1810,910,1950,790,2300,800);ctx.strokeStyle='#4b4b36';ctx.lineWidth=118;ctx.stroke();ctx.strokeStyle='#938365';ctx.lineWidth=103;ctx.stroke();ctx.strokeStyle='rgba(190,166,117,.24)';ctx.lineWidth=4;ctx.setLineDash([3,18]);ctx.stroke();ctx.restore();
// little pond
const pg=ctx.createRadialGradient(1740,370,15,1740,370,210);pg.addColorStop(0,'#527d75');pg.addColorStop(.8,'#315b55');pg.addColorStop(1,'#294a43');ctx.fillStyle=pg;ctx.beginPath();ctx.ellipse(1740,370,210,115,-.2,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#85916a';ctx.lineWidth=8;ctx.stroke();ctx.strokeStyle='rgba(178,203,159,.35)';ctx.lineWidth=2;for(let i=0;i<5;i++){ctx.beginPath();ctx.ellipse(1715+i*11,350+i*7,60+i*15,18+i*5,-.2,0,Math.PI*2);ctx.stroke()}
for(const f of flowers){if(f.x<camera.x-60||f.x>camera.x+innerWidth+60||f.y<camera.y-60||f.y>camera.y+innerHeight+60)continue;ctx.fillStyle=f.c;ctx.globalAlpha=.72;ctx.beginPath();ctx.arc(f.x,f.y,1.5,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
for(const s of stones){if(s.x<camera.x-40||s.x>camera.x+innerWidth+40||s.y<camera.y-40||s.y>camera.y+innerHeight+40)continue;ctx.fillStyle='#626650';ctx.beginPath();ctx.ellipse(s.x,s.y,s.r*1.35,s.r*.7,-.3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#86876d';ctx.beginPath();ctx.ellipse(s.x-2,s.y-2,s.r*.7,s.r*.45,-.3,0,Math.PI*2);ctx.fill()}
}
function drawTree(t){ctx.save();ctx.translate(t.x,t.y);ctx.fillStyle='rgba(17,26,17,.26)';ctx.beginPath();ctx.ellipse(2,5,t.r*1.12,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#503e2b';ctx.fillRect(-6,-t.h*.35,12,t.h*.4);const greens=['#314f36','#3c5a3b','#4a6340','#385338'];for(let j=0;j<3;j++){ctx.fillStyle=greens[Math.floor(t.t*10+j)%greens.length];ctx.beginPath();ctx.ellipse((j-1)*t.r*.28,-t.h*.66+j*7,t.r*(.75+j*.05),t.r*.6,(-.2+j*.2),0,Math.PI*2);ctx.fill()}ctx.fillStyle='rgba(186,187,115,.15)';ctx.beginPath();ctx.ellipse(-t.r*.25,-t.h*.8,t.r*.28,t.r*.2,-.4,0,Math.PI*2);ctx.fill();ctx.restore()}
function shadow(x,y,r){ctx.fillStyle='rgba(13,20,13,.35)';ctx.beginPath();ctx.ellipse(x,y,r,7,0,0,Math.PI*2);ctx.fill()}
function drawMob(m){if(!m.alive)return;shadow(m.x,m.y+7,17);ctx.save();ctx.translate(m.x,m.y+Math.sin(m.anim||0)*2);ctx.fillStyle=m.hit>0?'#d9b8a0':'#6d8654';ctx.beginPath();ctx.ellipse(0,-14,14,18,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#839a65';ctx.beginPath();ctx.arc(0,-32,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d5c48d';ctx.beginPath();ctx.moveTo(-7,-41);ctx.lineTo(-14,-51);ctx.lineTo(-4,-45);ctx.moveTo(6,-42);ctx.lineTo(13,-51);ctx.lineTo(3,-45);ctx.fill();ctx.fillStyle='#edcc83';ctx.fillRect(-5,-35,2.4,2);ctx.fillRect(3,-35,2.4,2);ctx.strokeStyle='#394c32';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-7,-3);ctx.lineTo(-10,3);ctx.moveTo(7,-3);ctx.lineTo(10,3);ctx.stroke();if(m===targetMob&&targetMob?.alive){ctx.fillStyle='#25271f';ctx.fillRect(-18,-61,36,4);ctx.fillStyle='#b65e4d';ctx.fillRect(-18,-61,36*m.hp/m.maxHp,4)}ctx.restore()}
function drawNpc(){shadow(npc.x,npc.y+5,16);ctx.save();ctx.translate(npc.x,npc.y);ctx.fillStyle='#756f53';ctx.beginPath();ctx.moveTo(-14,-3);ctx.lineTo(-12,-27);ctx.lineTo(0,-42);ctx.lineTo(12,-27);ctx.lineTo(14,-3);ctx.closePath();ctx.fill();ctx.fillStyle='#d1b782';ctx.beginPath();ctx.arc(0,-40,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ddd0ac';ctx.beginPath();ctx.moveTo(-11,-43);ctx.quadraticCurveTo(0,-59,11,-43);ctx.lineTo(8,-48);ctx.lineTo(-8,-48);ctx.fill();ctx.strokeStyle='#7b6743';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(15,-3);ctx.lineTo(18,-48);ctx.stroke();ctx.fillStyle='#e2c47d';ctx.beginPath();ctx.arc(0,-66,5+Math.sin(worldClock*3)*1,0,Math.PI*2);ctx.fill();ctx.restore();ctx.font='10px DM Sans';ctx.textAlign='center';ctx.fillStyle='#f3dfaa';ctx.fillText('✦ Elder Rowan',npc.x,npc.y-75)}
function drawPlayer(){shadow(player.x,player.y+7,17);ctx.save();ctx.translate(player.x,player.y);if(player.dodge>0)ctx.globalAlpha=.55;ctx.scale(player.dir,1);const bob=Math.sin(player.anim*9)*1.5;ctx.fillStyle=player.attack>0?'#d9a968':'#476a68';ctx.beginPath();ctx.moveTo(-13,-3);ctx.lineTo(-11,-28+bob);ctx.lineTo(0,-36+bob);ctx.lineTo(11,-28+bob);ctx.lineTo(14,-3);ctx.closePath();ctx.fill();ctx.fillStyle='#e5c193';ctx.beginPath();ctx.arc(0,-39+bob,8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#49513d';ctx.beginPath();ctx.moveTo(-9,-42+bob);ctx.lineTo(-5,-51+bob);ctx.lineTo(4,-51+bob);ctx.lineTo(9,-42+bob);ctx.closePath();ctx.fill();ctx.fillStyle='#c7a86c';ctx.fillRect(-12,-10+bob,24,3);ctx.strokeStyle='#bfc0ad';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(11,-24+bob);ctx.lineTo(19+(player.attack>0?12:0),-40+bob);ctx.stroke();ctx.strokeStyle='#8c613d';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(13,-28+bob);ctx.lineTo(20+(player.attack>0?12:0),-42+bob);ctx.stroke();ctx.restore()}
let targetMob=null;
function frame(now){const dt=Math.min((now-last)/1000,.05);last=now;update(dt);ctx.clearRect(0,0,innerWidth,innerHeight);camera.x=Math.max(0,Math.min(W-innerWidth,player.x-innerWidth/2));camera.y=Math.max(0,Math.min(H-innerHeight,player.y-innerHeight/2));ctx.save();ctx.translate(-camera.x,-camera.y);drawGround();for(const t of trees)if(t.x>camera.x-80&&t.x<camera.x+innerWidth+80&&t.y>camera.y-120&&t.y<camera.y+innerHeight+80)drawTree(t);const entities=[...mobs.filter(m=>m.alive).map(m=>({y:m.y,draw:()=>drawMob(m)})),{y:npc.y,draw:drawNpc},{y:player.y,draw:drawPlayer}].sort((a,b)=>a.y-b.y);for(const e of entities)e.draw();if(player.attack>0){ctx.strokeStyle='rgba(245,221,160,.52)';ctx.lineWidth=3;ctx.beginPath();ctx.arc(player.x+player.dir*17,player.y-28,28,-1.3,1.3);ctx.stroke()}ctx.restore();drawMini();requestAnimationFrame(frame)}
function update(dt){worldClock+=dt;player.anim+=dt;player.attack=Math.max(0,player.attack-dt*2);player.dodge=Math.max(0,player.dodge-dt);skillCooldown=Math.max(0,skillCooldown-dt);if(skillCooldown>0){document.getElementById('skill-cd').style.display='grid';document.getElementById('skill-cd').textContent=skillCooldown.toFixed(1)}else document.getElementById('skill-cd').style.display='none';
let dx=(keys.ArrowRight||keys.d?1:0)-(keys.ArrowLeft||keys.a?1:0),dy=(keys.ArrowDown||keys.s?1:0)-(keys.ArrowUp||keys.w?1:0);if(moveTarget){dx=moveTarget.x-player.x;dy=moveTarget.y-player.y;if(Math.hypot(dx,dy)<12){moveTarget=null;dx=dy=0}else{dx/=Math.hypot(dx,dy);dy/=Math.hypot(dx,dy)}}if(dx||dy){const l=Math.hypot(dx,dy);dx/=l;dy/=l;player.x=Math.max(32,Math.min(W-32,player.x+dx*158*dt*(player.dodge>0?2.3:1)));player.y=Math.max(32,Math.min(H-32,player.y+dy*158*dt*(player.dodge>0?2.3:1)));player.dir=dx<0?-1:1;player.anim+=dt*6;}
for(const m of mobs){if(m.hit>0)m.hit-=dt;if(!m.alive){m.respawn-=dt;if(m.respawn<=0){m.alive=true;m.hp=m.maxHp}continue}const d=Math.hypot(player.x-m.x,player.y-m.y);if(d<175){m.x+=(player.x-m.x)/d*28*dt;m.y+=(player.y-m.y)/d*28*dt;if(d<48&&Math.random()<dt*.55){damagePlayer(5)}}if(m===targetMob&&d<68&&attackTimer<=0){attackTimer=.72;player.attack=.25;m.hp-=14;m.hit=.15;if(m.hp<=0)killMob(m)}}if(attackTimer>0)attackTimer-=dt;document.getElementById('hpbar').style.width=(player.hp/player.maxHp*100)+'%';const near=Math.hypot(player.x-npc.x,player.y-npc.y)<78;document.getElementById('interaction').classList.toggle('show',near);document.getElementById('target').classList.toggle('show',!!targetMob&&targetMob.alive);if(targetMob){document.getElementById('target-hp').style.width=(targetMob.hp/targetMob.maxHp*100)+'%'}document.getElementById('coords').textContent=`${Math.floor(player.x/100)}, ${Math.floor(player.y/100)}`}
function damagePlayer(n){if(player.dodge>0)return;player.hp=Math.max(0,player.hp-n);if(player.hp<=0){player.hp=player.maxHp;player.x=1110;player.y=790;toast('You were rescued and returned to the glade.')} }
function addChat(text,klass='sys'){const d=document.createElement('div');d.className='chat-line';d.innerHTML=`<span class="${klass}">${text}</span>`;chat.appendChild(d);while(chat.children.length>5)chat.removeChild(chat.firstChild)}
function notify(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function killMob(m){m.alive=false;m.respawn=11;m.hp=0;targetMob=null;player.xp+=25;const n=Number(document.getElementById('quest-count').textContent.split('/')[0])+1;document.getElementById('quest-count').textContent=`${Math.min(n,3)} / 3`;document.getElementById('quest-progress').style.width=(Math.min(n,3)/3*100)+'%';addChat('A wildling has been defeated.','sys');notify('Wildling defeated · +25 XP');if(n>=3&&!window.questDone){window.questDone=true;player.xp+=75;notify('Quest complete! +75 XP · 12 silver');addChat('[Quest] A Trouble in the Glade complete!','sys')}while(player.xp>=player.level*100){player.xp-=player.level*100;player.level++;player.maxHp+=15;player.hp=player.maxHp;document.getElementById('level').textContent=player.level;notify(`Level up! You are now level ${player.level}`)}document.getElementById('xp-label').textContent=`${player.xp} / ${player.level*100} XP`}
function attack(){if(targetMob&&targetMob.alive){const d=Math.hypot(player.x-targetMob.x,player.y-targetMob.y);if(d>75){moveTarget={x:targetMob.x,y:targetMob.y};notify('Closing in...')}else{player.attack=.28;targetMob.hp-=14;targetMob.hit=.2;if(targetMob.hp<=0)killMob(targetMob)}}else notify('Select a wildling to attack.')}
function useSkill(){if(skillCooldown>0){notify('Whirlwind is recharging.');return}skillCooldown=5;player.attack=.5;let hit=0;for(const m of mobs)if(m.alive&&Math.hypot(player.x-m.x,player.y-m.y)<105){m.hp-=28;m.hit=.25;hit++;if(m.hp<=0)killMob(m)}notify(hit?`Whirlwind hits ${hit} wildling${hit>1?'s':''}!`:'Whirlwind!')}
function usePotion(){if(player.hp===player.maxHp){notify('Your health is already full.');return}player.hp=Math.min(player.maxHp,player.hp+45);notify('Healing potion · +45 health')}
function interact(){if(Math.hypot(player.x-npc.x,player.y-npc.y)<90)showDialogue();else notify('Move closer to Elder Rowan.')}
function drawMini(){const w=mini.width,h=mini.height;mctx.clearRect(0,0,w,h);mctx.fillStyle='#3b593d';mctx.fillRect(0,0,w,h);mctx.fillStyle='#887b5b';mctx.lineWidth=12;mctx.beginPath();mctx.moveTo(-10,120);mctx.quadraticCurveTo(70,80,120,110);mctx.quadraticCurveTo(170,130,250,60);mctx.stroke();mctx.fillStyle='#3c6961';mctx.beginPath();mctx.ellipse(190,37,29,17,-.2,0,Math.PI*2);mctx.fill();for(const t of trees){const x=t.x/W*w,y=t.y/H*h;mctx.fillStyle='#29432f';mctx.beginPath();mctx.arc(x,y,2.5,0,Math.PI*2);mctx.fill()}for(const m of mobs)if(m.alive){mctx.fillStyle='#db7564';mctx.fillRect(m.x/W*w-1,m.y/H*h-1,3,3)}mctx.fillStyle='#e8ca76';mctx.beginPath();mctx.arc(npc.x/W*w,npc.y/H*h,3,0,Math.PI*2);mctx.fill();mctx.fillStyle='#f5ecd0';mctx.beginPath();mctx.arc(player.x/W*w,player.y/H*h,3.8,0,Math.PI*2);mctx.fill();mctx.strokeStyle='rgba(245,236,208,.5)';mctx.lineWidth=1;mctx.stroke()}

function showDialogue(){dialogOpen=true;const done=!!window.questDone;document.getElementById('modal').innerHTML=`<button class="close">×</button><div class="eyebrow">Villager · Whispering Glade</div><h2>Elder Rowan</h2><div class="sub">Keeper of the Greenwold</div><p class="dialog-text">${done?'You have done the glade a great kindness, traveler. The wildlings are retreating. Take this, with the thanks of our people.':'The wildlings have grown bold since the old ward-stone cracked. They roam the eastern path and frighten our gatherers. Will you help us thin their numbers?'}</p><div class="dialog-actions"><button class="gold-button" id="accept-quest">${done?'Thank you':'I will help'}</button><button class="gold-button" id="dialog-bye" style="background:#2c3329;border-color:#62674e">Goodbye</button></div>`;document.getElementById('modal-wrap').classList.add('show');document.querySelector('.close').onclick=closeModal;document.getElementById('dialog-bye').onclick=closeModal;document.getElementById('accept-quest').onclick=()=>{closeModal();if(!done){notify('Quest accepted: A Trouble in the Glade');addChat('[Quest] Defeat 3 wildlings.','sys')}else notify('The elder bows gratefully.')};}
function showModal(which){const el=document.getElementById('modal');let title='',body='';if(which==='inventory'){title='Adventurer’s satchel';body=`<div class="inventory-grid"><div class="inv-slot">🧪<span>3</span></div><div class="inv-slot">🪵<span>2</span></div><div class="inv-slot">🪙<span>12</span></div>${Array.from({length:12},()=>'<div class="inv-slot"></div>').join('')}</div><div class="inventory-note">Healing potion restores <b style="color:#e6c478">45 health</b>. Use with <span class="kbd">3</span>.<br>Silver: <b style="color:#e6c478">12</b> &nbsp;·&nbsp; Bag space: <b>3 / 20</b></div>`}else if(which==='character'){title='Aren, Wayfarer';body=`<div class="sub">Level ${player.level} · Greenwold Wanderer</div><div class="inventory-note" style="line-height:2.2;margin-top:18px">❤ Health <b style="float:right;color:#e6c478">${Math.ceil(player.hp)} / ${player.maxHp}</b><br>✦ Experience <b style="float:right;color:#e6c478">${player.xp} / ${player.level*100}</b><br>⚔ Attack <b style="float:right;color:#e6c478">14</b><br>🛡 Defense <b style="float:right;color:#e6c478">5</b><br>✧ Gold <b style="float:right;color:#e6c478">12 silver</b></div>`}else if(which==='map'){title='The Greenwold';body=`<canvas id="bigmap" width="360" height="220" style="display:block;width:100%;margin-top:16px;border:1px solid #68704e;border-radius:4px"></canvas><div class="inventory-note">You are in <b style="color:#e6c478">Whispering Glade</b>, on the eastern edge of the old forest. Elder Rowan is marked in gold.</div>`}else{title='Realm settings';body=`<div class="inventory-note" style="margin-top:18px">A quiet moment under the boughs.<br><br><label><input id="sound-toggle" type="checkbox" checked> Ambient sound effects</label><br><br><span class="kbd">W A S D</span> or arrows · Move<br><span class="kbd">Click</span> to move or target<br><span class="kbd">E</span> Talk · <span class="kbd">1–5</span> Abilities</div>`}
el.innerHTML=`<button class="close">×</button><h2>${title}</h2><div class="sub">${which==='inventory'?'Items & currency':which==='map'?'Eastern Reach · Spring':'Character & realm'}</div>${body}`;document.getElementById('modal-wrap').classList.add('show');document.querySelector('.close').onclick=closeModal;if(which==='map'){const c=document.getElementById('bigmap'),g=c.getContext('2d');g.fillStyle='#3b593d';g.fillRect(0,0,360,220);g.fillStyle='#887b5b';g.lineWidth=19;g.beginPath();g.moveTo(-20,170);g.quadraticCurveTo(95,125,155,150);g.quadraticCurveTo(230,175,380,70);g.stroke();g.fillStyle='#3c6961';g.beginPath();g.ellipse(285,55,48,28,-.2,0,Math.PI*2);g.fill();for(const t of trees){g.fillStyle='#29432f';g.beginPath();g.arc(t.x/W*360,t.y/H*220,3.8,0,Math.PI*2);g.fill()}for(const m of mobs)if(m.alive){g.fillStyle='#db7564';g.beginPath();g.arc(m.x/W*360,m.y/H*220,3,0,Math.PI*2);g.fill()}g.fillStyle='#e8ca76';g.beginPath();g.arc(npc.x/W*360,npc.y/H*220,4,0,Math.PI*2);g.fill();g.fillStyle='#fff0c1';g.beginPath();g.arc(player.x/W*360,player.y/H*220,5,0,Math.PI*2);g.fill()}}
function closeModal(){document.getElementById('modal-wrap').classList.remove('show');dialogOpen=false}
document.getElementById('modal-wrap').addEventListener('click',e=>{if(e.target.id==='modal-wrap')closeModal()});
canvas.addEventListener('pointermove',e=>{mouse.x=e.clientX;mouse.y=e.clientY;let hovering=false;for(const m of mobs){if(m.alive&&Math.hypot(e.clientX+camera.x-m.x,e.clientY+camera.y-m.y)<28){hovering=true;break}}canvas.style.cursor=hovering?'crosshair':'default'});
canvas.addEventListener('pointerdown',e=>{if(dialogOpen)return;const x=e.clientX+camera.x,y=e.clientY+camera.y;let closest=null,dist=Infinity;for(const m of mobs){const d=Math.hypot(x-m.x,y-m.y);if(m.alive&&d<38&&d<dist){closest=m;dist=d}}if(closest){targetMob=closest;moveTarget=null;document.getElementById('target').querySelector('.target-name').textContent=`Mossback Wildling · ${closest.id+1}`;if(Math.hypot(player.x-closest.x,player.y-closest.y)<85)attack();else moveTarget={x:closest.x,y:closest.y};return}if(Math.hypot(x-npc.x,y-npc.y)<48){if(Math.hypot(player.x-npc.x,player.y-npc.y)<90)showDialogue();else moveTarget={x:npc.x,y:npc.y};return}targetMob=null;moveTarget={x,y};});
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key==='Escape'){closeModal();return}if(document.activeElement===document.getElementById('chat-message'))return;keys[e.key.toLowerCase()]=true;keys[e.key]=true;if(e.repeat)return;if(e.key.toLowerCase()==='e')interact();if(e.key==='1')attack();if(e.key==='2')useSkill();if(e.key==='3')usePotion();if(e.key==='4'){player.dodge=.32;moveTarget=null;notify('Dodge!')}if(e.key==='5'){player.anim+=2;addChat('Aren waves to nearby adventurers.','you')} });addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;keys[e.key]=false});
document.querySelectorAll('.slot').forEach(b=>b.addEventListener('click',()=>{const a=b.dataset.action;if(a==='attack')attack();if(a==='skill')useSkill();if(a==='potion')usePotion();if(a==='dodge'){player.dodge=.32;moveTarget=null;notify('Dodge!')}if(a==='emote')addChat('Aren waves to nearby adventurers.','you')}));
document.querySelectorAll('.icon-btn').forEach(b=>b.addEventListener('click',()=>showModal(b.dataset.modal)));
document.getElementById('chat-form').addEventListener('submit',e=>{e.preventDefault();const input=document.getElementById('chat-message'),v=input.value.trim();if(v){addChat('[Aren] '+v,'you');input.value=''}});
